        var st = x.st === 'done' ? '<span class="tag ok">' + t('fu.done') + '</span>' : x.st === 'overdue' ? '<span class="tag due">' + t('fu.overdue') + '</span>' : x.st === 'soon' ? '<span class="tag">' + t('fu.soon') + '</span>' : '<span class="muted">' + t('fu.planned') + '</span>';
