  var h = '<div class="head"><div><div class="kicker">' + (['planner', 'mdt'].indexOf(k) >= 0 ? t('side.work') : t('side.research')) + '</div><h1>' + esc(L(c.title)) + '</h1><p class="sub">' + esc(L(c.sub)) + '</p></div><div class="actions">';
