  var IN = function () { return [qo('Совсем не мешали', 'Not at all', 0), qo('Немного', 'A little bit', 1), qo('Отчасти', 'Somewhat', 2), qo('Значительно', 'Quite a bit', 3), qo('Очень сильно', 'Very much', 4)]; };
