function fimpNorm(s) { return String(s || '').toLowerCase().replace(/[a-z]/g, function (c) { return { a: 'а', c: 'с', e: 'е', o: 'о', p: 'р', x: 'х', y: 'у', m: 'м', k: 'к', t: 'т', h: 'н', b: 'в' }[c] || c; }).replace(/ё/g, 'е').replace(/\([^)]*\)/g, ' ').replace(/[^а-яa-z0-9]+/g, ' ').trim(); }
