      h += '</div>' + (randLocked ? '' : '<button type="button" class="btn small" data-act="elistadd" data-list="proto.rand.arms" data-tpl=\'{"name":"","limit":""}\'>' + ico('plus', 15) + LL('Добавить группу', 'Add arm') + '</button>');
