      ev.push({ id: 'pc:' + (c.id || p.id + c.ts), ts: c.ts, type: 'cmt', ic: 'chat', t: c.by + LL(' прокомментировал(а) карточку', ' commented on a record') + where, s: pName(p) + ': ' + String(c.text || '').slice(0, 140), go: ['p', p.id] });
