  a.push({ id: uid('d'), name: name, at: nowIso(), text: text.slice(0, ARCH_DOC), sum: sum || '' });
  var tot = 0; for (var i = a.length - 1; i >= 0; i--) { tot += (a[i].text || '').length; if (tot > ARCH_ALL) a[i].text = ''; }
