    mdtNext: null, mm: [], rc: [].filter(function (r) { return r.done !== 'Заполнено' && r.contact === td; }).map(function (r) { return { k: 'redcap', id: r.id, name: nm(r.fio, r.pid), x: r.rid || '' }; })
