  DB.cols.mdt.forEach(function (r) { if (ev[r.date]) ev[r.date].push({ c: 'mdt', t: LL('МДГ: ', 'MDT: ') + (r.fio || ''), s: r.mrn ? '№ ' + r.mrn : '', a: ['r', 'mdt', r.id] }); });
