  var cms = Object.keys(m.cm).map(function (k) { return m.cm[k]; }).filter(function (c) { return c.paper === cur.id && !c.parent; }).sort(function (a, b) { return String(b.at).localeCompare(String(a.at)); });
  h += '<div class="pp-head"><input type="text" class="pp-title" data-pmeta="' + sid + '.' + cur.id + '.title" value="' + esc(cur.title || '') + '" placeholder="' + LL('Название статьи', 'Paper title') + '"' + (msCanEdit() ? '' : ' readonly') + '>';
  h += '<div class="pp-tools"><span class="muted">' + esc(PAPER_TPL[cur.tpl] ? L(PAPER_TPL[cur.tpl][0]) : '') + ' · ' + total + LL(' слов', ' words') + ' · ' + ord.length + LL(' ссылок', ' citations') + '</span><label class="fsel"><select data-pstyle="' + sid + '.' + cur.id + '">' + CITE_STYLES.map(function (s2) { return '<option value="' + s2[0] + '"' + (s2[0] === style ? ' selected' : '') + '>' + LL('Стиль: ', 'Style: ') + L(s2[1]) + '</option>'; }).join('') + '</select></label><button type="button" class="btn" data-act="paperdoc" data-id="' + sid + '">' + ico('download', 15) + 'Word</button>' + (function () { var pz = msPresence(cur); return pz.length ? '<span class="pp-pres" title="' + LL('Сейчас открыли этот документ', 'Viewing now') + '">' + pz.map(function (n) { return '<span class="av sm">' + esc(initials(n)) + '</span>'; }).join('') + '<em>' + esc(pz.join(', ')) + '</em></span>' : ''; })() + '<button type="button" class="btn" data-act="paperread" data-id="' + sid + '">' + ico('eye', 15) + (S.paperRead ? LL('Редактор', 'Editor') : LL('Как в журнале', 'Preview')) + '</button></div></div>';
  h += '<div class="pp-body"><nav class="pp-nav">' + secs.map(function (s) { return '<button type="button" data-act="msjump" data-id="ms-' + s.id + '"><span>' + esc(secTitle(s)) + '</span><em>' + words(s.text) + '</em>' + (s.lock && !msLockFree(s) ? ico('lock', 12) : '') + '</button>'; }).join('') + '<button type="button" data-act="msjump" data-id="ms-refs"><span>' + LL('Список литературы', 'References') + '</span><em>' + ord.length + '</em></button>' + (msCanEdit() ? '<button type="button" class="add" data-act="secadd" data-id="' + sid + '">' + ico('plus', 13) + LL('Раздел', 'Section') + '</button>' : '') + '</nav>';
  h += '<div class="pp-main">';
